64	import org.springframework.web.bind.annotation.RequestMapping;
65	import org.springframework.web.bind.annotation.RestController;
66	import org.springframework.web.util.UriComponentsBuilder;
67	
68	import jakarta.transaction.Transactional;
69	
70	/**
71	 * @author Vitaliy Fedoriv
72	 */
73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
81	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.petMapper = petMapper;
100	        this.visitMapper = visitMapper;
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
106	        Collection<Owner> owners;
107	        if (lastName != null) {
108	            owners = this.clinicService.findOwnerByLastName(lastName);
109	        } else {
110	            owners = this.clinicService.findAllOwners();
111	        }
112	        if (owners.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
121	        Owner owner = this.clinicService.findOwnerById(ownerId);
122	        if (owner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
126	    }
127	
128	    /**
129	     * Rejects an owner payload that is missing or blank in any of the required fields
130	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
131	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
132	     * value as present; this guard closes that gap so a blank in any required field is
133	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
134	     * the name of each offending field.
135	     */
136	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
137	        List<String> missing = new ArrayList<>();
138	        if (isBlank(ownerFieldsDto.getFirstName())) {
139	            missing.add("firstName");
140	        }
141	        if (isBlank(ownerFieldsDto.getLastName())) {
142	            missing.add("lastName");
143	        }
144	        if (isBlank(normalizedAddress)) {
145	            missing.add("address");
146	        }
147	        if (isBlank(ownerFieldsDto.getCity())) {
148	            missing.add("city");
149	        }
150	        if (isBlank(ownerFieldsDto.getTelephone())) {
151	            missing.add("telephone");
152	        }
153	        if (!missing.isEmpty()) {
154	            throw new MissingOwnerFieldsException(missing);
155	        }
156	    }
157	
158	    private static boolean isBlank(String value) {
159	        return value == null || value.isBlank();
160	    }
161	
162	    /**
163	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
164	     */
165	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
166	
167	    /**
168	     * Required national-number length per country calling code. When the normalized E.164 number
169	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
170	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
171	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
172	     */
173	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
174	        "+61", 9,
175	        "+1", 10);
176	
177	    /**
178	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
179	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
180	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
181	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
182	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
183	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
184	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
185	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
186	     * translates to a 400.
187	     */
188	    private static String normalizeTelephone(String telephone) {
189	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
190	        String e164;
191	        if (cleaned.startsWith("+")) {
192	            e164 = cleaned;
193	        } else {
194	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
195	            e164 = "+61" + national;
196	        }
197	        if (!E164_PATTERN.matcher(e164).matches()) {
198	            throw new InvalidTelephoneException(telephone);
199	        }
200	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
201	            String code = rule.getKey();
202	            if (e164.startsWith(code)) {
203	                int nationalLength = e164.length() - code.length();
204	                if (nationalLength != rule.getValue()) {
205	                    throw new InvalidTelephoneException(telephone);
206	                }
207	                break;
208	            }
209	        }
210	        return e164;
211	    }
212	
213	    /**
214	     * Matches a well-formed postcode: exactly four digits.
215	     */
216	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
217	
218	    /**
219	     * The canonical region for each city that has one. A city absent from this table has no known
220	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
221	     * to derive an owner's locality.
222	     */
223	    private static final Map<String, String> CITY_REGION = Map.of(
224	        "Sydney", "NSW",
225	        "Melbourne", "VIC",
226	        "Brisbane", "QLD");
227	
228	    /**
229	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
230	     * VIC 3000-3099, QLD 4000-4099.
231	     */
232	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
233	        "NSW", new int[] {2000, 2099},
234	        "VIC", new int[] {3000, 3099},
235	        "QLD", new int[] {4000, 4099});
236	
237	    /**
238	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
239	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
240	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
241	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
242	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
243	     * exception handler translates to a 400.
244	     */
245	    private static void validatePostcode(String city, String postcode) {
246	        if (postcode == null) {
247	            return;
248	        }
249	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
250	            throw new InvalidPostcodeException(postcode);
251	        }
252	        String region = CITY_REGION.get(city);
253	        if (region == null) {
254	            return;
255	        }
256	        int[] range = REGION_POSTCODES.get(region);
257	        int value = Integer.parseInt(postcode);
258	        if (value < range[0] || value > range[1]) {
259	            throw new InvalidPostcodeException(postcode);
260	        }
261	    }
262	
263	    /**
264	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
265	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
266	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
267	     */
268	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
269	
270	    /**
271	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
272	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
273	     * fixed set so the block list is explicit and easy to extend.
274	     */
275	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
276	        "mailinator.com",
277	        "tempmail.com",
278	        "guerrillamail.com");
279	
280	    /**
281	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
282	     * optional). When present it must be a syntactically valid address whose domain is not on the
283	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
284	     * canonical form. An invalid or disposable-domain value is rejected via
285	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
286	     */
287	    private static String normalizeEmail(String email) {
288	        if (email == null) {
289	            return null;
290	        }
291	        if (!EMAIL_PATTERN.matcher(email).matches()) {
292	            throw new InvalidEmailException(email);
293	        }
294	        String normalized = email.toLowerCase(Locale.ROOT);
295	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
296	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
297	            throw new InvalidEmailException(email);
298	        }
299	        return normalized;
300	    }
301	
302	    /**
303	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
304	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
305	     * same identity only when this whole key matches: because the normalized telephone is part of
306	     * the key, two members of the same household (same {@code householdId}) with different
307	     * telephones have different identity keys. A {@code null} email contributes an empty middle
308	     * segment. This is the value returned to callers as {@code identityKey}.
309	     */
310	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
311	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
312	    }
313	
314	    /**
315	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
316	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
317	     * telephone, email and household checks are now expressed through the components of the single
318	     * identity key:
319	     * <ul>
320	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
321	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
322	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
323	     *       candidate email, being optional, is not compared, and existing owners without an email
324	     *       are skipped);</li>
325	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
326	     *       a household via {@code sharesHousehold}, in which case the household component is not
327	     *       compared.</li>
328	     * </ul>
329	     */
330	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
331	                                         String normalizedEmail, String householdId) {
332	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
333	        for (Owner existing : this.clinicService.findAllOwners()) {
334	            String existingTelephone;
335	            try {
336	                existingTelephone = normalizeTelephone(existing.getTelephone());
337	            } catch (InvalidTelephoneException ex) {
338	                existingTelephone = null;
339	            }
340	            if (normalizedTelephone.equals(existingTelephone)) {
341	                throw new DuplicateTelephoneException(normalizedTelephone);
342	            }
343	            if (normalizedEmail != null) {
344	                String existingEmail = existing.getEmail();
345	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
346	                    throw new DuplicateEmailException(normalizedEmail);
347	                }
348	            }
349	            if (!sharesHousehold
350	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getPostcode()))) {
351	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
352	            }
353	        }
354	    }
355	
356	    /**
357	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
358	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
359	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
360	     * spacing do not defeat the duplicate-household check.
361	     */
362	    private static String collapse(String value) {
363	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
364	    }
365	
366	    /**
367	     * Normalizes an owner's address into a canonical form applied on every create: leading and
368	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
369	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
370	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
371	     * and returned, and is the form every address comparison (duplicate-household detection and the
372	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
373	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
374	     * so normalizing an already-normalized address is a no-op.
375	     */
376	    private static String normalizeAddress(String address) {
377	        if (address == null) {
378	            return "";
379	        }
380	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
381	        if (collapsed.isEmpty()) {
382	            return "";
383	        }
384	        String[] tokens = collapsed.split(" ");
385	        StringBuilder sb = new StringBuilder(collapsed.length());
386	        for (int i = 0; i < tokens.length; i++) {
387	            String token = tokens[i];
388	            switch (token) {
389	                case "ST" -> token = "STREET";
390	                case "RD" -> token = "ROAD";
391	                case "AVE" -> token = "AVENUE";
392	                default -> {
393	                }
394	            }
395	            if (i > 0) {
396	                sb.append(' ');
397	            }
398	            sb.append(token);
399	        }
400	        return sb.toString();
401	    }
402	
403	    /**
404	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
405	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
406	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
407	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
408	     * region derivation shared by the {@code customerCode} and the owner's locality.
409	     */
410	    private static String deriveRegion(String city, String postcode) {
411	        if (postcode != null) {
412	            try {
413	                int pc = Integer.parseInt(postcode.trim());
414	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
415	                    int[] bounds = range.getValue();
416	                    if (pc >= bounds[0] && pc <= bounds[1]) {
417	                        return range.getKey();
418	                    }
419	                }
420	            } catch (NumberFormatException ignored) {
421	                // not a numeric postcode; fall back to the city-to-region table
422	            }
423	        }
424	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
425	    }
426	
427	    /**
428	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
429	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
430	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
431	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
432	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
433	     */
434	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
435	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
436	    }
437	
438	    /**
439	     * De-duplicates a freshly computed {@code customerCode} against the codes already carried by
440	     * existing owners. When the base code is unused it is returned unchanged; otherwise
441	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
442	     * existing owner already holds. The count reflects the state prior to this create.
443	     */
444	    private String deduplicateCustomerCode(String baseCode) {
445	        Set<String> existingCodes = new HashSet<>();
446	        for (Owner existing : this.clinicService.findAllOwners()) {
447	            String code = existing.getCustomerCode();
448	            if (code != null) {
449	                existingCodes.add(code);
450	            }
451	        }
452	        if (!existingCodes.contains(baseCode)) {
453	            return baseCode;
454	        }
455	        int n = 2;
456	        while (existingCodes.contains(baseCode + "-" + n)) {
457	            n++;
458	        }
459	        return baseCode + "-" + n;
460	    }
461	
462	    /**
463	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
464	     * bytes of {@code value}.
465	     */
466	    private static String sha256HexPrefix(String value, int hexChars) {
467	        try {
468	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
469	            StringBuilder sb = new StringBuilder(hexChars);
470	            for (byte b : digest) {
471	                if (sb.length() >= hexChars) {
472	                    break;
473	                }
474	                sb.append(String.format("%02X", b));
475	            }
476	            return sb.substring(0, hexChars);
477	        } catch (NoSuchAlgorithmException ex) {
478	            throw new IllegalStateException("SHA-256 not available", ex);
479	        }
480	    }
481	
482	    /**
483	     * Builds the {@code membershipNumber} for a newly created owner, formatted
484	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
485	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
486	     */
487	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
488	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
489	    }
490	
491	    /**
492	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
493	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
494	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
495	     * it is a pure function of that pair, every owner in the same household - whether created first
496	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
497	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
498	     * segment.
499	     */
500	    private static String householdIdFor(String lastName, String postcode) {
501	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
502	        try {
503	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
504	            StringBuilder sb = new StringBuilder(12);
505	            for (byte b : digest) {
506	                if (sb.length() >= 12) {
507	                    break;
508	                }
509	                sb.append(String.format("%02x", b));
510	            }
511	            return sb.substring(0, 12);
512	        } catch (NoSuchAlgorithmException ex) {
513	            throw new IllegalStateException("SHA-256 not available", ex);
514	        }
515	    }
516	
517	    /**
518	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
519	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
520	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
521	     */
522	    private int countNamesakes(String firstName, String lastName) {
523	        int count = 0;
524	        for (Owner existing : this.clinicService.findAllOwners()) {
525	            if (firstName.equalsIgnoreCase(existing.getFirstName())
526	                && lastName.equalsIgnoreCase(existing.getLastName())) {
527	                count++;
528	            }
529	        }
530	        return count;
531	    }
532	
533	    /**
534	     * Counts the members of the household the new owner will belong to, as it stands after this
535	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
536	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
537	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
538	     * stored on the owner as its {@code householdMemberCount}.
539	     */
540	    private int countHouseholdMembers(String householdId) {
541	        int count = 1;
542	        for (Owner existing : this.clinicService.findAllOwners()) {
543	            if (householdId.equals(existing.getHouseholdId())) {
544	                count++;
545	            }
546	        }
547	        return count;
548	    }
549	
550	    /**
551	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
552	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
553	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
554	     * new owner's postcode must be present for a soft match to be possible. When several existing
555	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
556	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
557	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
558	     *
559	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
560	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
561	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
562	     * household member is not a suspected duplicate, so no soft match is reported in that case.
563	     */
564	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
565	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
566	            return null;
567	        }
568	        String postcode = ownerFieldsDto.getPostcode();
569	        if (postcode == null) {
570	            return null;
571	        }
572	        String lastName = ownerFieldsDto.getLastName();
573	        Integer matchId = null;
574	        for (Owner existing : this.clinicService.findAllOwners()) {
575	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
576	                continue;
577	            }
578	            if (!postcode.equals(existing.getPostcode())) {
579	                continue;
580	            }
581	            String existingTelephone;
582	            try {
583	                existingTelephone = normalizeTelephone(existing.getTelephone());
584	            } catch (InvalidTelephoneException ex) {
585	                existingTelephone = null;
586	            }
587	            if (normalizedTelephone.equals(existingTelephone)) {
588	                continue;
589	            }
590	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
591	                matchId = existing.getId();
592	            }
593	        }
594	        return matchId;
595	    }
596	
597	    /**
598	     * The tenure, in days, that an owner must exceed before its tenure contributes membership
599	     * points. Tenure is measured from the owner's {@code registrationDate}, so a newly created owner
600	     * (whose tenure is zero) never satisfies this and thus never earns the tenure points on create.
601	     */
602	    private static final int TENURE_POINTS_THRESHOLD_DAYS = 365;
603	
604	    /**
605	     * The household size (number of members) at or above which an owner earns the household points.
606	     */
607	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
608	
609	    /**
610	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
611	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
612	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
613	     * (days elapsed since its {@code registrationDate}) exceeds {@value #TENURE_POINTS_THRESHOLD_DAYS}
614	     * days. Because a newly created owner has zero tenure, the tenure points never apply on create.
615	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
616	     * have been set.
617	     */
618	    private static int membershipPointsFor(Owner owner) {
619	        int points = 0;
620	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
621	            points += 2;
622	        }
623	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
624	            points += 1;
625	        }
626	        if (owner.getHouseholdMemberCount() != null
627	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
628	            points += 2;
629	        }
630	        if (tenureInDays(owner) > TENURE_POINTS_THRESHOLD_DAYS) {
631	            points += 3;
632	        }
633	        return points;
634	    }
635	
636	    /**
637	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
638	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
639	     */
640	    private static int membershipLevelForPoints(int points) {
641	        if (points <= 1) {
642	            return 1;
643	        }
644	        if (points <= 3) {
645	            return 2;
646	        }
647	        if (points <= 5) {
648	            return 3;
649	        }
650	        return 4;
651	    }
652	
653	    /**
654	     * The owner's tenure in whole days: the number of days elapsed from its {@code registrationDate}
655	     * up to the current server date. An owner with no registration date, or one dated in the future,
656	     * has a tenure of zero.
657	     */
658	    private static long tenureInDays(Owner owner) {
659	        LocalDate registrationDate = owner.getRegistrationDate();
660	        if (registrationDate == null) {
661	            return 0;
662	        }
663	        return Math.max(0, ChronoUnit.DAYS.between(registrationDate, LocalDate.now()));
664	    }
665	
666	    /**
667	     * The maximum number of owners any single city may contain. A create whose city already
668	     * holds this many owners is rejected.
669	     */
670	    private static final int CITY_CAPACITY = 50;
671	
672	    /**
673	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
674	     * compared case-insensitively - the same way the city is matched when building the
675	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
676	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
677	     * translates to a 409.
678	     */
679	    private void rejectCityAtCapacity(String city) {
680	        int count = 0;
681	        for (Owner existing : this.clinicService.findAllOwners()) {
682	            if (city.equalsIgnoreCase(existing.getCity())) {
683	                count++;
684	            }
685	        }
686	        if (count >= CITY_CAPACITY) {
687	            throw new CityAtCapacityException(city);
688	        }
689	    }
690	
691	    /**
692	     * The maximum number of owners that may be created on any single day (by
693	     * {@code registrationDate}). A create attempted once this many owners already carry the
694	     * current day's registration date is rejected.
695	     */
696	    private static final int DAILY_OWNER_LIMIT = 100;
697	
698	    /**
699	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
700	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
701	     * The count reflects the state prior to this create. When the limit is reached the create is
702	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
703	     * to a 429 Too Many Requests.
704	     */
705	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
706	        int count = 0;
707	        for (Owner existing : this.clinicService.findAllOwners()) {
708	            if (registrationDate.equals(existing.getRegistrationDate())) {
709	                count++;
710	            }
711	        }
712	        if (count >= DAILY_OWNER_LIMIT) {
713	            throw new DailyOwnerLimitExceededException();
714	        }
715	    }
716	
717	    /**
718	     * The number of owners that must already carry a given {@code registrationDate} before a
719	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
720	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
721	     */
722	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
723	
724	    /**
725	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
726	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
727	     * have already been created for that date, otherwise false. The count reflects the state prior
728	     * to this create, matching how the daily-limit rule accumulates.
729	     */
730	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
731	        int count = 0;
732	        for (Owner existing : this.clinicService.findAllOwners()) {
733	            if (registrationDate.equals(existing.getRegistrationDate())) {
734	                count++;
735	            }
736	        }
737	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
738	    }
739	
740	    /**
741	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
742	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
743	     * effective registration date - whether supplied in the request or defaulted to the server
744	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
745	     * on a business day.
746	     */
747	    /**
748	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
749	     * only ever explicitly supplied on the request; when present it must not be later than the
750	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
751	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
752	     * later from the server date) is accepted.
753	     */
754	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
755	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
756	            throw new FutureRegistrationDateException(registrationDate);
757	        }
758	    }
759	
760	    private static LocalDate toBusinessDay(LocalDate date) {
761	        return switch (date.getDayOfWeek()) {
762	            case SATURDAY -> date.plusDays(2);
763	            case SUNDAY -> date.plusDays(1);
764	            default -> date;
765	        };
766	    }
767	
768	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
769	    @Override
770	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
771	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
772	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
773	        rejectCityAtCapacity(ownerFieldsDto.getCity());
774	        HttpHeaders headers = new HttpHeaders();
775	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
776	        owner.setAddress(normalizedAddress);
777	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
778	        owner.setTelephone(normalizedTelephone);
779	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
780	        owner.setEmail(normalizedEmail);
781	        validatePostcode(owner.getCity(), owner.getPostcode());
782	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
783	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
784	        rejectFutureRegistrationDate(owner.getRegistrationDate());
785	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
786	        LocalDate registrationDate = toBusinessDay(effectiveDate);
787	        rejectDailyOwnerLimit(registrationDate);
788	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
789	        owner.setRegistrationDate(registrationDate);
790	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
791	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName())));
792	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
793	        owner.setHouseholdId(householdId);
794	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
795	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
796	        int membershipPoints = membershipPointsFor(owner);
797	        owner.setMembershipPoints(membershipPoints);
798	        owner.setMembershipLevel(membershipLevelForPoints(membershipPoints));
799	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
800	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
801	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
802	        this.clinicService.saveOwner(owner);
803	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
804	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(), owner.getMembershipNumber());
805	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
806	        headers.setLocation(UriComponentsBuilder.newInstance()
807	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
808	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
809	    }
810	
811	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
812	    @Override
813	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
814	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
815	        if (currentOwner == null) {
816	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
817	        }
818	        currentOwner.setAddress(ownerFieldsDto.getAddress());
819	        currentOwner.setCity(ownerFieldsDto.getCity());
820	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
821	        currentOwner.setLastName(ownerFieldsDto.getLastName());
822	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
823	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
824	        this.clinicService.saveOwner(currentOwner);
825	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
826	    }
827	
828	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
829	    @Transactional
830	    @Override
831	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
832	        Owner owner = this.clinicService.findOwnerById(ownerId);
833	        if (owner == null) {
834	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
835	        }
836	        this.clinicService.deleteOwner(owner);
837	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
838	    }
839	
840	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
841	    @Override
842	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
843	        Owner owner = this.clinicService.findOwnerById(ownerId);
844	        if (owner == null) {
845	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
846	        }
847	        HttpHeaders headers = new HttpHeaders();
848	        Pet pet = petMapper.toPet(petFieldsDto);
849	        owner.setId(ownerId);
850	        pet.setOwner(owner);
851	        pet.getType().setName(null);
852	        this.clinicService.savePet(pet);
853	        PetDto petDto = petMapper.toPetDto(pet);
854	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
855	            .buildAndExpand(pet.getId()).toUri());
856	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
857	    }
858	
859	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
860	    @Override
861	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
862	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
863	        if (currentOwner != null) {
864	            Pet currentPet = this.clinicService.findPetById(petId);
865	            if (currentPet != null) {
866	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
867	                currentPet.setName(petFieldsDto.getName());
868	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
869	                this.clinicService.savePet(currentPet);
870	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
871	            }
872	        }
873	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
874	    }
875	
876	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
877	    @Override
878	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
879	        HttpHeaders headers = new HttpHeaders();
880	        Visit visit = visitMapper.toVisit(visitFieldsDto);
881	        Pet pet = new Pet();
882	        pet.setId(petId);
883	        visit.setPet(pet);
884	        this.clinicService.saveVisit(visit);
885	        VisitDto visitDto = visitMapper.toVisitDto(visit);
886	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
887	            .buildAndExpand(visit.getId()).toUri());
888	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
889	    }
890	
891	
892	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
893	    @Override
894	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
895	        Owner owner = this.clinicService.findOwnerById(ownerId);
896	        if (owner != null) {
897	            Pet pet = owner.getPet(petId);
898	            if (pet != null) {
899	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
900	            }
901	        }
902	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
903	    }
904	}
