1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner == null ? null : owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(owner == null ? null : "
25	            + "Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
26	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
27	    @Mapping(target = "locality", expression = "java(deriveLocality(owner))")
28	    @Mapping(target = "timezone", expression = "java(deriveTimezone(owner))")
29	    @Mapping(target = "contactPreference",
30	        expression = "java(owner == null ? null : "
31	            + "(owner.getEmail() != null && !owner.getEmail().isEmpty() ? \"EMAIL\" : \"PHONE\"))")
32	    @Mapping(target = "identityKey",
33	        expression = "java(owner == null ? null : owner.getTelephone() + \"|\" "
34	            + "+ (owner.getEmail() == null ? \"\" : owner.getEmail()) + \"|\" "
35	            + "+ (owner.getHouseholdId() == null ? \"\" : owner.getHouseholdId()))")
36	    @Mapping(target = "checkDigit", expression = "java(deriveCheckDigit(owner))")
37	    @Mapping(target = "ageBand", expression = "java(deriveAgeBand(owner))")
38	    @Mapping(target = "telephoneDisplay", expression = "java(deriveTelephoneDisplay(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    Owner toOwner(OwnerDto ownerDto);
42	
43	    @Mapping(target = "id", ignore = true)
44	    @Mapping(target = "pets", ignore = true)
45	    Owner toOwner(OwnerFieldsDto ownerDto);
46	
47	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
48	
49	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
50	
51	    /**
52	     * Derive the owner's locality (region) from its region-and-hash {@code customerCode}: the
53	     * {@code REGION} portion is the segment before the first {@code '-'} (e.g. {@code "NSW-1A2B3C4D"}
54	     * yields {@code "NSW"}). This shares the identity's region derivation, where the postcode range
55	     * takes precedence (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and the city-to-region table is
56	     * the fallback. For an owner without a {@code customerCode} the same region is recomputed directly
57	     * from the postcode then city, otherwise "UNKNOWN".
58	     */
59	    default String deriveLocality(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        String customerCode = owner.getCustomerCode();
64	        if (customerCode != null) {
65	            int dash = customerCode.indexOf('-');
66	            if (dash > 0) {
67	                return customerCode.substring(0, dash);
68	            }
69	        }
70	        String postcode = owner.getPostcode();
71	        if (postcode != null) {
72	            try {
73	                int pc = Integer.parseInt(postcode.trim());
74	                if (pc >= 2000 && pc <= 2099) {
75	                    return "NSW";
76	                }
77	                if (pc >= 3000 && pc <= 3099) {
78	                    return "VIC";
79	                }
80	                if (pc >= 4000 && pc <= 4099) {
81	                    return "QLD";
82	                }
83	            }
84	            catch (NumberFormatException ignored) {
85	                // not a numeric postcode; fall back to the city-to-region table
86	            }
87	        }
88	        String city = owner.getCity();
89	        if ("Sydney".equals(city)) {
90	            return "NSW";
91	        }
92	        if ("Melbourne".equals(city)) {
93	            return "VIC";
94	        }
95	        if ("Brisbane".equals(city)) {
96	            return "QLD";
97	        }
98	        return "UNKNOWN";
99	    }
100	
101	    /**
102	     * Derive the owner's IANA timezone from its locality/region using the fixed region-to-timezone
103	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). The region is
104	     * the same value reported as {@code locality}. Returns null when the owner is absent or the region
105	     * has no known timezone.
106	     */
107	    default String deriveTimezone(Owner owner) {
108	        if (owner == null) {
109	            return null;
110	        }
111	        String region = deriveLocality(owner);
112	        if ("NSW".equals(region)) {
113	            return "Australia/Sydney";
114	        }
115	        if ("VIC".equals(region)) {
116	            return "Australia/Melbourne";
117	        }
118	        if ("QLD".equals(region)) {
119	            return "Australia/Brisbane";
120	        }
121	        return null;
122	    }
123	
124	    /**
125	     * Derive the owner's check digit: a single Luhn check digit (0-9) computed over the
126	     * digits contained in the owner's customerCode. Non-digit characters are ignored.
127	     * Returns null when the owner or its customerCode is absent.
128	     */
129	    default Integer deriveCheckDigit(Owner owner) {
130	        if (owner == null || owner.getCustomerCode() == null) {
131	            return null;
132	        }
133	        String code = owner.getCustomerCode();
134	        int sum = 0;
135	        boolean dbl = true;
136	        for (int i = code.length() - 1; i >= 0; i--) {
137	            char c = code.charAt(i);
138	            if (c < '0' || c > '9') {
139	                continue;
140	            }
141	            int d = c - '0';
142	            if (dbl) {
143	                d *= 2;
144	                if (d > 9) {
145	                    d -= 9;
146	                }
147	            }
148	            sum += d;
149	            dbl = !dbl;
150	        }
151	        return (10 - (sum % 10)) % 10;
152	    }
153	
154	    /**
155	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
156	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
157	     * years between birthDate and registrationDate (falling back to the current date when the owner
158	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
159	     * ageBand is reported.
160	     */
161	    default String deriveAgeBand(Owner owner) {
162	        if (owner == null || owner.getBirthDate() == null) {
163	            return null;
164	        }
165	        java.time.LocalDate reference = owner.getRegistrationDate() != null
166	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
167	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
168	        if (age < 18) {
169	            return "MINOR";
170	        }
171	        if (age < 65) {
172	            return "ADULT";
173	        }
174	        return "SENIOR";
175	    }
